const $ = <T extends HTMLElement>(sel: string): T => root.querySelector<T>(sel)!
const gate = $<HTMLElement>('.gate')
const waiting = $<HTMLElement>('.waiting')
const who = $<HTMLElement>('#who')
const linkStatus = $<HTMLElement>('#link-status')
const glassesLine = $<HTMLElement>('#glasses')
const steerEl = $<HTMLElement>('.hud-steer')
const labelEl = $<HTMLElement>('.hud-label')
const whyEl = $<HTMLElement>('.hud-why')
const cueEl = $<HTMLElement>('.hud-cue')
const cueText = $<HTMLElement>('.hud-cue-text')
const statusEl = $<HTMLElement>('.hud-status')

bindDeviceToggles(root, device, (d) => {
  for (const el of root.querySelectorAll('.device-name')) el.textContent = DEVICE_NAME[d]
})

let glasses: GlassesRenderer | null = null
let channel: CompanionChannel | null = null
let lastFrame: Frame | null = null
let wasActive = false
let leaveTimer: ReturnType<typeof setTimeout> | null = null

// MARK: - Rendering the HUD from Stage frames

function show(el: HTMLElement, on: boolean): void {
  if (on) {
    el.hidden = false
    el.classList.remove('show')
    void el.offsetWidth
    el.classList.add('show')
  } else {
    el.classList.remove('show')
  }
}

function applyFrame(frame: Frame): void {
  const prev = lastFrame
  lastFrame = frame
  statusEl.textContent = frame.footer

  if (frame.kind === 'cue') {
    cueText.textContent = frame.primary
    if (prev?.kind !== 'cue' || prev.primary !== frame.primary) {
      show(cueEl, true)
      earcon.play('cue')
    }
    show(steerEl, false)
    return
  }
  show(cueEl, false)

  if (frame.kind === 'steer') {
    if (prev?.kind !== 'steer' || prev.primary !== frame.primary) {
      labelEl.textContent = frame.primary
      whyEl.textContent = frame.secondary
      show(steerEl, true)
      earcon.play('steer')
    }
    return
  }
  show(steerEl, false)

  if (frame.kind === 'status' && frame.primary) {
    // Paused / calibrating: quiet, in the why slot's register, not a steer.
    labelEl.textContent = ''
    whyEl.textContent = frame.primary
    steerEl.hidden = false
    steerEl.classList.add('show')
  }
}

function enterLive(): void {
  if (leaveTimer) clearTimeout(leaveTimer)
  leaveTimer = null
  waiting.hidden = true
  root.classList.add('on')
}

function leaveLive(): void {
  statusEl.textContent = t.callEnded
  leaveTimer = setTimeout(() => {
    root.classList.remove('on')
    statusEl.textContent = ''
    if (!gate.hidden) return
    waiting.hidden = false
  }, 1600)
}

function tick(): void {
  const frame = stage.frame()
  const active = stage.sessionActive
  if (active && !wasActive) enterLive()
  if (!active && wasActive) leaveLive()
  wasActive = active
  if (!sameFrame(lastFrame, frame)) {
    applyFrame(frame)
    void glasses?.render(frame)
  }
}
setInterval(tick, 250)

// MARK: - Auth + channel

function setLink(status: ChannelStatus, detail?: string): void {
  linkStatus.className = `status ${status === 'connected' ? 'on' : status === 'error' ? 'warn' : ''}`
  // Connected needs no line — the "Connected as …" eyebrow already says it.
  linkStatus.textContent = status === 'connected' ? '' : status === 'error' ? t.channelError : t.connecting
  if (detail) linkStatus.title = detail
}

async function openChannel(userId: string): Promise<void> {
  if (!channel) channel = new CompanionChannel()
  await channel.open(userId, {
    onState: (e) => stage.onState(e),
    onSteer: (e) => stage.onSteer(e),
    onCue: (e) => stage.onCue(e),
    // The other party's lines ride the wire for a phone-side transcript
    // surface; this page shows only what the glass shows.
    onCaption: () => undefined,
    onStatus: setLink,
  })
}

async function closeChannel(): Promise<void> {
  await channel?.close()
}

function renderSignedIn(email: string | null): void {
  if (!email) gateMode(inApp ? 'email' : 'providers')
  if (email) {
    who.textContent = `${t.connectedAs} ${email}`
    gate.hidden = true
    if (!stage.sessionActive) waiting.hidden = false
  } else {
    gate.hidden = false
    waiting.hidden = true
    root.classList.remove('on')
  }
}

// MARK: - The gate: Google / Apple / Microsoft, or email + password, or a one-time code
//
// Most TalkPilot accounts have no password — they were created with Google
// or Apple on the phone (Alexis's own is Google-only, which is why the first
// cut's password form could never let him in, 2026-09-05). OAuth runs
// through Supabase's hosted flow and returns to this exact page (PKCE); the
// page's URL has to be on the project's redirect allow-list for that to
// land. Inside the Even app's WebView a browser redirect can't come back,
// so there the gate offers only the one-time code.

const providers = $<HTMLElement>('#providers')
const form = $<HTMLFormElement>('#signin')
const codeForm = $<HTMLFormElement>('#code')
const codeHint = $<HTMLElement>('#code-hint')
const inAppHint = $<HTMLElement>('#in-app-hint')
const error = $<HTMLParagraphElement>('#signin-error')
let codeEmail = ''

/** This page's own URL, minus any auth leftovers, as the place OAuth and magic links return to. */
function returnUrl(): string {
  const u = new URL(location.href)
  u.hash = ''
  for (const k of ['code', 'error', 'error_code', 'error_description', 'access_token', 'refresh_token', 'token_type', 'expires_in', 'type']) u.searchParams.delete(k)
  return u.toString()
}

function showError(prefix: string, detail?: string | null): void {
  error.textContent = detail ? `${prefix} ${detail}` : prefix
  error.hidden = false
}

function gateMode(mode: 'providers' | 'email' | 'code'): void {
  providers.hidden = mode !== 'providers'
  form.hidden = mode !== 'email'
  codeForm.hidden = mode !== 'code'
  error.hidden = true
  if (mode === 'email') form.querySelector<HTMLInputElement>('input[name=email]')?.focus()
  if (mode === 'code') codeForm.querySelector<HTMLInputElement>('input[name=token]')?.focus()
}

function busy(button: HTMLButtonElement, on: boolean, label: string): void {
  button.disabled = on
  button.textContent = label
}

/** Supabase's messages, translated where a user can act on them. */
function describe(err: { message: string; code?: string }): string | null {
  const m = err.message.toLowerCase()
  if (m.includes('invalid login credentials')) return t.wrongPassword
  if (m.includes('email not confirmed')) return t.emailNotConfirmed
  return null
}

providers.addEventListener('click', async (ev) => {
  const b = (ev.target as HTMLElement).closest<HTMLButtonElement>('.provider')
  if (!b) return
  await earcon.unlock() // the one user gesture we get
  const provider = b.dataset.provider as 'google' | 'apple' | 'azure'
  busy(b, true, t.signingIn)
  const { error: err } = await supabase.auth.signInWithOAuth({
    provider,
    options: {
      redirectTo: returnUrl(),
      // Microsoft: personal and work accounts alike, as the iOS app does.
      ...(provider === 'azure' ? { scopes: 'email openid profile' } : {}),
    },
  })
  // On success the browser is already navigating away.
  if (err) {
    busy(b, false, `${t.continueWith} ${provider === 'azure' ? 'Microsoft' : provider === 'apple' ? 'Apple' : 'Google'}`)
    showError(t.signInFailed, err.message)
  }
})

$<HTMLButtonElement>('#use-email').addEventListener('click', () => gateMode('email'))
$<HTMLButtonElement>('#use-providers').addEventListener('click', () => gateMode(inApp ? 'email' : 'providers'))
$<HTMLButtonElement>('#code-back').addEventListener('click', () => gateMode(inApp ? 'email' : 'providers'))

form.addEventListener('submit', async (ev) => {
  ev.preventDefault()
  await earcon.unlock()
  const button = form.querySelector<HTMLButtonElement>('button[type=submit]')!
  busy(button, true, t.signingIn)
  error.hidden = true
  const data = new FormData(form)
  const { error: err } = await supabase.auth.signInWithPassword({
    email: String(data.get('email') ?? '').trim(),
    password: String(data.get('password') ?? ''),
  })
  busy(button, false, t.signIn)
  if (err) showError(describe(err) ?? t.signInFailed, describe(err) ? null : err.message)
})

$<HTMLButtonElement>('#send-code').addEventListener('click', async (ev) => {
  const b = ev.currentTarget as HTMLButtonElement
  const email = String(new FormData(form).get('email') ?? '').trim()
  if (!email) {
    form.querySelector<HTMLInputElement>('input[name=email]')?.reportValidity()
    return
  }
  await earcon.unlock()
  busy(b, true, t.sendingCode)
  error.hidden = true
  const { error: err } = await supabase.auth.signInWithOtp({
    email,
    // Never mint an account from this page; the phone app owns sign-up.
    options: { shouldCreateUser: false, emailRedirectTo: returnUrl() },
  })
  busy(b, false, t.sendCode)
  if (err) {
    showError(t.codeFailed, err.message)
    return
  }
  codeEmail = email
  codeHint.textContent = `${t.codeSent} ${email}.`
  gateMode('code')
})

codeForm.addEventListener('submit', async (ev) => {
  ev.preventDefault()
  const button = codeForm.querySelector<HTMLButtonElement>('button[type=submit]')!
  busy(button, true, t.verifying)
  error.hidden = true
  const token = String(new FormData(codeForm).get('token') ?? '').trim()
  const { error: err } = await supabase.auth.verifyOtp({ email: codeEmail, token, type: 'email' })
  busy(button, false, t.verify)
  if (err) showError(t.codeWrong)
})

// An OAuth return that failed carries the reason in the URL; say it, then tidy the URL.
{
  const q = new URLSearchParams(location.search)
  const desc = q.get('error_description') ?? q.get('error')
  if (desc) showError(t.signInFailed, desc.replace(/\+/g, ' '))
}

// Inside the Even app (a Flutter WebView) there is no browser to come back
// from, so the code is the only way in. Decided at boot once the bridge is known.
let inApp = false

$<HTMLButtonElement>('#signout').addEventListener('click', () => void supabase.auth.signOut())

// MARK: - Ring input (real glasses) → phone

function onInput(input: GlassesInput): void {
  const command: CommandType =
    input === 'tap' ? 'requestSuggestion' : input === 'doubleTap' ? 'requestReflection' : stage.isPaused ? 'resumeSession' : 'pauseSession'
  void channel?.send(command)
}

// MARK: - Boot

async function boot(): Promise<void> {
  glasses = await GlassesRenderer.connect()
  glassesLine.hidden = !glasses
  glasses?.onInput(onInput)
  inApp = !!glasses
  if (inApp) {
    inAppHint.hidden = false
    providers.hidden = true
    form.hidden = false
    // Password fields are a chore on a phone keyboard inside a WebView; the
    // code path is the one that works everywhere, so lead with it.
    form.querySelector<HTMLInputElement>('input[name=password]')!.required = false
    $<HTMLButtonElement>('#use-providers').hidden = true
  }

  const {
    data: { session },
  } = await supabase.auth.getSession()
  renderSignedIn(session?.user.email ?? null)
  if (session) await openChannel(session.user.id)
  // Back from OAuth or a magic link: the session is stored; drop the code from the URL.
  if (/[?&](code|access_token|error)=/.test(location.search + location.hash)) history.replaceState(null, '', returnUrl())

  supabase.auth.onAuthStateChange((_event, next) => {
    renderSignedIn(next?.user.email ?? null)
    if (next) void openChannel(next.user.id)
    else void closeChannel()
  })
}

void boot()

// Dev-only hook so the waiting and live states can be exercised without a
// real account (Playwright, this sandbox). Tree-shaken out of production.
if (import.meta.env.DEV) {
  ;(window as unknown as { __tp: unknown }).__tp = {
    signedIn: (email: string | null) => renderSignedIn(email),
    state: (s: Parameters<Stage['onState']>[0]) => stage.onState(s),
    steer: (s: Parameters<Stage['onSteer']>[0]) => stage.onSteer(s),
    cue: (c: Parameters<Stage['onCue']>[0]) => stage.onCue(c),
  }
}
